-- Starter set of Steinhardt-specific content — the setting's signature
-- named monsters (the "Падшие Охотники" boss NPCs) and magic items (the
-- Potustoronniye Ornaments chapter). Not an exhaustive transcription of the
-- full bestiary/equipment chapters (hundreds of entries) — standard D&D
-- content is looked up live against open5e instead (see moonsApi-style
-- bestiaryApi), and more Steinhardt-only rows can be added the same way
-- this file was: read the book, insert a row.

insert into steinhart_monsters (name, challenge_rating, creature_type, book_page, summary) values
  ('Охотник в Вуали', '7', 'Аберрация', 380, 'Падший охотник-друид, сросшийся с деревьями: атаки на дистанции, тюрьма из корней, телепорт между деревьями, маска даёт сопротивление магии.'),
  ('Извращённый Библиотекарь', '11', 'Нежить', 382, 'Призрачный заклинатель-некромант (остеомантия), левитирует, аура тишины, отражает заклинания, при 0 хитов раз в день восстанавливает все хиты и часть ячеек.'),
  ('Тисифона, Первозданный Хаос', '14', 'Аберрация', 384, 'Друид-мутант из Круга Симбиоза: регенерация, легендарные действия, при 0 хитов уходит в неуязвимую сферу и возрождается.'),
  ('Малах, Ангел Плоти', '15', 'Конструкт', 386, 'Механический "ангел" в облачении из плоти убитых: ядовитые миазмы, легендарные действия, форма и способности меняются при полу-хитах.'),
  ('Король Охоты', '28', 'Гуманоид и Аберрация', 397, 'Финальный босс Падших Охотников — бессмертный воин (не теряет сознание при 0 хитов), иммунитет к немагическому физическому урону, скорость не замедлить.')
on conflict (name) do nothing;

insert into steinhart_items (name, category, rarity, book_page, summary) values
  ('Проклятие Лунной Крови', 'Потусторонний орнамент', 'редкая/оч.редкая/легендарная (зависит от способа нанесения)', 258, 'Превращает владельца в багряного зверя (Луннокровного) при определённых условиях — тема каннибализма/проклятия первых жертв Бедствия.'),
  ('Свинцовая Кровь', 'Потусторонний орнамент', 'варьируется', 260, 'Связан с состоянием берсерка: при завершении эффекта хиты падают до 0 и теряются все силы орнамента на неделю.'),
  ('Жертвенное Клеймо', 'Потусторонний орнамент', 'варьируется', 260, 'Получают воскрешённые Кровавой Луной Перерождения — помечает их как связанных с ней, усиливается во время её действия.'),
  ('Потомок Молнии', 'Потусторонний орнамент', 'варьируется', 261, 'Электрическая тема — см. книгу для точных эффектов по уровням нанесения (рисунок/татуировка/шрамирование).'),
  ('Благословение Навре', 'Потусторонний орнамент', 'варьируется', 263, 'См. книгу для точных эффектов.'),
  ('Мефитовая Печать', 'Потусторонний орнамент', 'варьируется', 263, 'Связан с ядовитыми/газовыми эффектами (мефит) — см. книгу для точных эффектов.'),
  ('Первый Орнамент', 'Потусторонний орнамент', 'варьируется', 264, 'Часть трилогии Первый/Второй/Третий Орнамент, тема праведного мстителя с "Клинком серафима".'),
  ('Второй Орнамент', 'Потусторонний орнамент', 'варьируется', 264, 'Продолжение линейки — усиливает Праведное возмездие и позволяет слить Клинок серафима с оружием.'),
  ('Третий Орнамент', 'Потусторонний орнамент', 'варьируется', 264, 'Финальная ступень линейки орнаментов серафима — см. книгу для точных эффектов.')
on conflict (name) do nothing;

-- Full pass over the equipment chapter (стр. 205-257): firearms-cannons,
-- wondrous items/potions, and every named "хитрое оружие" (transforming
-- trick weapon) — this is the rest of what "Предметы" has beyond the
-- Ornaments already seeded above. Rarity/weapon-pair comes straight from
-- each item's own header line in the book; summary is a 1-line paraphrase,
-- not the full rules text — see book_page for that.
insert into steinhart_items (name, category, rarity, book_page, summary) values
  ('Освященная Пушка', 'Огнестрельное оружие (пушка)', 'необычная', 212, 'Раз за ход можно заменить атаку мощным залпом по линии 120×5 футов.'),
  ('Большая Берта', 'Огнестрельное оружие (пушка)', 'редкая', 213, 'Инкрустирована лунным золотом, бонусным действием заряжает следующий выстрел одним из трёх стихийных эффектов.'),
  ('Сумка для Пушечных Ядер', 'Чудесный предмет', 'необычная', 206, 'Вмещает до 100 пушечных ядер почти без веса.'),
  ('Дамасцена', 'Чудесный предмет', 'необычная', 206, 'Устройство Потомков: конус синего пламени из свинцовых пуль.'),
  ('Рука Славы', 'Чудесный предмет', 'очень редкая', 207, 'Доп. настройка на кольцо + невидимость, пока горит палец; открывание на объекты в свету.'),
  ('Грибной Чай', 'Чудесный предмет (зелье)', 'варьируется', 207, 'Снимает приступ безумия на час, но нужен спасбросок Телосложения против рвоты (таблица по цвету чая).'),
  ('Святой Тоник', 'Зелье', 'необычное', 208, 'Лечит 4d4+4 хитов и болезни, но со скрытыми от игроков побочками безумия/проклятия при злоупотреблении.'),
  ('Позолоченное Луной Оружие', 'Апгрейд оружия', '—', 214, 'Покрытие оружия лунным золотом: +1d4 урона против негуманоидов, преим. на спасброски от испуга/безумия, истирается за 3 месяца.'),

  ('Гильотинные Ножницы', 'Хитрое оружие (длинный+короткий меч ↔ ножницы)', 'необычная', 216, 'В форме ножниц может реакцией "гильотинировать" — доп. урон, при высоком уроне отрубает конечность или обезглавливает.'),
  ('Усовершенствованные Гильотинные Ножницы', 'Хитрое оружие (длинный+короткий меч ↔ ножницы)', 'редкая', 244, 'Улучшенная версия Гильотинных Ножниц, увеличенный урон Гильотины.'),
  ('Мясной Крюкострел', 'Хитрое оружие (мушкетон+серп ↔ топор-мушкетон)', 'необычная', 217, 'В трансформированной форме может выстрелить серпом-крюком на цепи и притянуть цель к себе (или себя к цели).'),
  ('Усовершенствованный Мясной Крюкострел', 'Хитрое оружие (мушкетон+серп ↔ топор-мушкетон)', 'редкая', 226, 'Крюкострел с большей дальностью крюка и доп. эффектом при двойном попадании.'),
  ('Освященный Соратник', 'Хитрое оружие (копьё+щит ↔ глефа)', 'необычная', 218, 'Копьё со щитом, реакцией парирует атаки; в форме глефы щит остаётся пронзённым в цели, замедляя её.'),
  ('Гравитационный Соратник', 'Хитрое оружие (копьё+щит ↔ глефа)', 'редкая', 223, 'Усиленная версия Освящённого Соратника — больше бонус КД и урон от застрявшего щита.'),
  ('Палка', 'Хитрое оружие (палка ↔ две палки)', 'необычная', 219, 'Шуточное оружие: ломается о колено на две палки, может сломаться при провале атаки.'),
  ('Нарезной Тесак', 'Хитрое оружие (тесак ↔ винтовка)', 'необычная', 220, 'После рукопашной атаки тесаком можно бонусным действием выстрелить из скрытой винтовки.'),
  ('Усовершенствованный Нарезной Тесак', 'Хитрое оружие (тесак ↔ винтовка)', 'редкая', 225, 'Улучшенная винтовочная форма с бóльшим стволом.'),
  ('Клинок-Топор Стража Бездны', 'Хитрое оружие (длинный меч ↔ боевой топор)', 'редкая', 220, 'Оба состояния наносят доп. урон излучением, усиленный против аберраций.'),
  ('Пробуждённый Клинок-Топор Стража Бездны', 'Хитрое оружие (длинный меч ↔ боевой топор)', 'очень редкая', 235, 'Улучшенная версия — больше урона и доп. эффекты при трансформации/попадании.'),
  ('Кордицепс Синенсис', 'Хитрое оружие (особое — паразит)', 'редкая', 221, 'Вживляемый грибок-паразит: усик ↔ руки-щупальца, раз в сутки не даёт умереть (хиты падают до 1 вместо 0), риск потери контроля при частых смертях.'),
  ('Палач Мечтаний', 'Хитрое оружие (коса+фонарь ↔ молот)', 'редкая (настройка)', 222, 'Фонарь ловит души умерших рядом (блокирует воскрешение) и может взорвать захваченную душу для урона.'),
  ('Призрачный Палач', 'Хитрое оружие (коса+фонарь ↔ молот)', 'очень редкая', 248, 'Улучшенная версия Палача Мечтаний.'),
  ('Электрический Цепной Меч', 'Хитрое оружие (длинный меч)', 'редкая', 223, 'Заряды электричества, парирование реакцией, доп. урон рубящий+электрический в трансформации.'),
  ('Незаряженный Коготь', 'Хитрое оружие (перчатка ↔ когти)', 'редкая (настройка)', 232, 'Сопротивление электричеству, тратит Кости Хитов на доп. урон, заряды блокируют входящий урон электричеством/звуком.'),
  ('Гальванизированный Коготь', 'Хитрое оружие (перчатка ↔ когти)', 'очень редкая (настройка)', 243, 'Улучшенная версия Незаряженного Когтя — получается, раздавив сердце гальванизированного хищника.'),
  ('Нестабильный Измельчитель', 'Хитрое оружие (пушка ↔ молот)', 'редкая (настройка)', 234, 'Двойной урон сооружениям; критические броски атаки (15+) дают доп. взрывной эффект.'),
  ('Разрушительный Измельчитель', 'Хитрое оружие (пушка ↔ молот)', 'очень редкая (настройка)', 235, 'Усиленная версия Нестабильного Измельчителя — эффект огненного шара при крите.'),
  ('Кальдера', 'Хитрое оружие (боевой топор ↔ пара пистолей)', 'очень редкая (настройка)', 236, 'Топор с тиглем расплавленного свинца, трансформируется в пару пистолей с "Пулевым адом" (6 выстрелов разом).'),
  ('Кровавый Клинок', 'Хитрое оружие (длинный меч ↔ двуручный меч)', 'очень редкая (настройка)', 238, 'Копит заряды кровью противников, тратит их на лечение/доп. урон/опутывание/оглушение.'),
  ('Жаждущий Кровавый Клинок', 'Хитрое оружие (длинный меч ↔ двуручный меч)', 'артефакт (настройка)', 256, 'Вершина линейки Кровавого Клинка.'),
  ('Солнечный Клинок', 'Хитрое оружие (двуручный меч ↔ короткий меч)', 'очень редкая (настройка)', 239, 'Тема Лучезарной церкви — излучающий урон, см. книгу для деталей.'),
  ('Освобождённый Солнечный Клинок', 'Хитрое оружие (двуручный меч ↔ короткий меч)', 'артефакт (настройка)', 257, 'Вершина линейки Солнечного Клинка.'),
  ('Позолоченная Луной Смоляная Кровь', 'Хитрое оружие (длинный лук ↔ длинный меч)', 'редкая (настройка)', 227, 'Доступ к вариантам "Кровавого выстрела" лучника; попадания замедляют цель смолой.'),
  ('Позолоченный Луной Уравнитель', 'Хитрое оружие (кремневый пистоль ↔ винтовка)', 'редкая', 228, 'Можно заменить атаку мощным выстрелом на 2d8 колющего, оружие временно "перегревается".'),
  ('Эфирный Позолоченный Луной Уравнитель', 'Хитрое оружие (кремневый пистоль ↔ винтовка)', 'очень редкая (настройка)', 239, 'Улучшенная версия Позолоченного Луной Уравнителя.'),
  ('Искусственный Лунный Свет', 'Хитрое оружие (коса ↔ длинный лук)', 'очень редкая', 244, 'См. книгу для точных эффектов.'),
  ('Осколок Лунного Света', 'Хитрое оружие (длинный меч ↔ двуручный меч)', 'артефакт (настройка)', 254, 'Лунная тема, высокий урон падением/светом — см. книгу.'),
